-- Hourwise schema (PostgreSQL 14+).
--
-- Applied by `sqlx::migrate!` (see src/migrate.rs). Never edit this file once it has been applied
-- to a database: add a new numbered file instead. The checksum is recorded in `_sqlx_migrations`.
--
-- Types: ids are UUIDs generated by the application, dates are DATE, timestamps are TIMESTAMPTZ
-- (stored in UTC), durations are whole minutes. Foreign keys cascade, and the application also
-- deletes children explicitly inside a transaction (see routes/admin.rs).

-- Users: admins and members. Emails are stored lower-cased, so UNIQUE is case-insensitive.
CREATE TABLE users (
    id            UUID        PRIMARY KEY,
    email         TEXT        NOT NULL UNIQUE CHECK (email = lower(email) AND email <> ''),
    name          TEXT        NOT NULL,
    password_hash TEXT        NOT NULL,
    role          TEXT        NOT NULL DEFAULT 'member' CHECK (role IN ('admin', 'member')),
    job_title     TEXT,
    avatar_url    TEXT,
    is_active     BOOLEAN     NOT NULL DEFAULT TRUE,
    -- Incremented to revoke every session of the user (password change/reset, deactivation).
    session_epoch BIGINT      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE projects (
    id          UUID        PRIMARY KEY,
    name        TEXT        NOT NULL,
    client      TEXT,
    description TEXT,
    color       TEXT        NOT NULL DEFAULT '#f36c00',
    is_archived BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE project_members (
    project_id UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    added_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);
CREATE INDEX project_members_user_idx ON project_members (user_id);

CREATE TABLE time_entries (
    id          UUID        PRIMARY KEY,
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    project_id  UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    entry_date  DATE        NOT NULL,
    minutes     INTEGER     NOT NULL CHECK (minutes > 0 AND minutes <= 1440),
    description TEXT        NOT NULL DEFAULT '',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- A member's own timesheet and the 24h daily cap: WHERE user_id = ? AND entry_date ...
CREATE INDEX time_entries_user_date_idx ON time_entries (user_id, entry_date);
-- Project detail and project-filtered reports: WHERE project_id = ? AND entry_date ...
CREATE INDEX time_entries_project_date_idx ON time_entries (project_id, entry_date);
-- Admin reports and dashboard stats across all users: WHERE entry_date BETWEEN ? AND ?
CREATE INDEX time_entries_date_idx ON time_entries (entry_date);
